'use strict';

let baseOG,baseRot,baseScale;
let ogOff,rotOff,scaleOff;
let ogOffM, rotOffM, scaleOffM;
let sqrRadius;

export var scriptProperties = createScriptProperties()
	.addSlider({
		name: 'time',
		label: 'Time',
		value: 1,
		min: 0,
		max: 10,
		integer: false
	})
	.addSlider({
		name: 'timeOffset',
		label: 'Time Offset',
		value: 0,
		min: -10,
		max: 10,
		integer: false
	})
	.addText({
		name: 'ogOff',
		label: 'Origin Offset',
		value: '0,0,0',
	})
	.addText({
		name: 'rotOff',
		label: 'Rotation Offset',
		value: '0,0,0',
	})
	.addText({
		name: 'scaleOff',
		label: 'Scale Offset',
		value: '0,0,0',
	})
	.addCheckbox({
		name: 'useMouseOffset',
		label: 'Use Mouse Offsets',
		value: false
	})
	.addSlider({
		name: 'mouseRadius',
		label: 'Mouse Push Radius',
		value: 500,
		min: 0,
		max: 1500,
		integer: false
	})
	.addText({
		name: 'ogOffM',
		label: 'Mouse Origin Offset',
		value: '0,0,0',
	})
	.addText({
		name: 'rotOffM',
		label: 'Mouse Rotation Offset',
		value: '0,0,0',
	})
	.addText({
		name: 'scaleOffM',
		label: 'Mouse Scale Offset',
		value: '0,0,0',
	})	
	.finish();

/**
 * @param {String} value - vector string representation
 * @return {Vec3} - output vec3
 */
function ParseVec3(value){
	let split = value.split(',');
	return new Vec3(
		parseFloat(split[0]),
		parseFloat(split[1]),
		parseFloat(split[2])
	);
}

/**
 * @param {Boolean} value - for property 'visible'
 * @return {Boolean} - update current property value
 */
export function init(value) {

	baseOG = thisLayer.origin;
	baseScale = thisLayer.scale;
	baseRot = thisLayer.angles;

	ogOff = ParseVec3(scriptProperties.ogOff);
	rotOff = ParseVec3(scriptProperties.rotOff);
	scaleOff = ParseVec3(scriptProperties.scaleOff);

	ogOffM = ParseVec3(scriptProperties.ogOffM);
	rotOffM = ParseVec3(scriptProperties.rotOffM);
	scaleOffM = ParseVec3(scriptProperties.scaleOffM);

	sqrRadius = 1.0 / (scriptProperties.mouseRadius * scriptProperties.mouseRadius);

	return value;
}



let mouseDist = 0;
function approxRollingAverage(avg, new_sample, N) {
    avg -= avg / N;
    avg += new_sample / N;
    return avg;
}

/**
 * @param {Boolean} value - for property 'visible'
 * @return {Boolean} - update current property value
 */
export function update(value) {

	let cos = Math.cos((engine.runtime + scriptProperties.timeOffset) / scriptProperties.time) * 0.5 + 0.5;

	let og = baseOG.add(ogOff.multiply(cos));
	let rot = baseRot.add(rotOff.multiply(cos));
	let scale = baseScale.add(scaleOff.multiply(cos));

	if(scriptProperties.useMouseOffset){
		let dir = og.subtract(input.cursorWorldPosition);
		let dist = 1.0 - dir.lengthSqr() * sqrRadius;

		if(dist < mouseDist){
			mouseDist = Math.max(mouseDist * 0.95, dist);
		}else{
			mouseDist = approxRollingAverage(mouseDist, dist, 4);
		}

		if(mouseDist > 0){
			og = og.add(ogOffM.multiply(mouseDist));
			rot = rot.add(rotOffM.multiply(mouseDist));
			scale = scale.add(scaleOffM.multiply(mouseDist));
		}
	}

	thisLayer.origin = og;
	thisLayer.angles = rot;
	thisLayer.scale = scale;

	return value;
}

