	// 	value: false
	// })
	.addCheckbox({
		name: 'pmztz',
		label: '屏幕中拖拽',
		value: false
	})
	.addSlider({
		name: 'weizhix',
		label: 'X',
		value: 0,
		min: 0,
		max: 3840,
		integer: false
	})
	.addSlider({
		name: 'weizhiy',
		label: 'Y',
		value: 0,
		min: 0,
		max: 2160,
		integer: false
	})
	.addSlider({
		name: 'weizhiz',
		label: 'Z',
		value: 0,
		min: -2000,
		max: 2000,
		integer: false
	})
	.finish();

// 以90度为步长随机选择方向
// var direction = new Vec3(WEVector.angleVector2(45 + Math.floor(Math.random() * 4) * 90));
var direction = new Vec3
let isDragging = false;
let dragOffset;
let tuozuai = 1
let count = 0, firstClickTime;
let doubleClickFrameTime = 500; //毫秒
export function cursorClick(event) {

	count++;
	if (count % 2 !== 0) //如果点击次数是奇数（1、3、5）
	{
		firstClickTime = Date.now(); //记住点击的时间
	}
	if (count % 2 === 0) //如果点击次数是偶数（2、4、6）
	{
		if (Date.now() - firstClickTime > doubleClickFrameTime) //如果从第一次点击到第二次点击的时间超过双击的预期时间范围
		{
			firstClickTime = Date.now(); //记住新的时间
			count--; //-1 click
		}
		else //点击在双击的预期时间范围内
		{
			if (scriptProperties.tz){
			if (tuozuai == 1){
					tuozuai = 2
			}
			else if (tuozuai == 2){
			tuozuai = 1
			}
			count = 0; //重置点击次数
		}
	}
}
}

export function cursorDown(event) {	
	if(tuozuai == 2){
		isDragging = true;
	}
	dragOffset = thisLayer.origin.subtract(event.worldPosition);
}

export function cursorUp(event) {
	isDragging = false;
}
//拖拽
export function cursorMove(event) {
	if (isDragging) {
		thisLayer.origin = event.worldPosition.add(dragOffset);
		weizhi = thisLayer.origin;
		scriptProperties.weizhix = thisLayer.origin.x - weizhix;
		scriptProperties.weizhiy = thisLayer.origin.y - weizhiy;
		scriptProperties.weizhiz = thisLayer.origin.z - weizhiz;
	}
}

export function update(value) {

	value = weizhi;
//滑块
	value.x = scriptProperties.weizhix + weizhix;
	value.y = scriptProperties.weizhiy + weizhiy;
	value.z = scriptProperties.weizhiz + weizhiz;

	let scale = thisLayer.scale;
	let imageSize = thisLayer.size;
	let canvasSize = engine.canvasSize;

	// 我们需要从中心到边界的尺寸。
	imageSize.x *= scale.x * 0.5;
	imageSize.y *= scale.y * 0.5;

if (scriptProperties.pmztz && tuozuai == 2){

	// 击中屏幕边界并反映方向。
value.x = Math.min(Math.max(value.x, imageSize.x), canvasSize.x - imageSize.x);
value.y = Math.min(Math.max(value.y, imageSize.y), canvasSize.y - imageSize.y);

}

// if (scriptProperties.tt){
// value.x = Math.max(Math.min(value.x, canvasSize.x - imageSize.x), imageSize.x);
// value.y = Math.max(Math.min(value.y, canvasSize.y - imageSize.y), imageSize.y);
// const reflectVec = new Vec3(Math.sign(value.x - imageSize.x - canvasSize.x / 2), Math.sign(value.y - imageSize.y - canvasSize.y / 2), 0);
// direction = direction.reflect(reflectVec);
// }


console.log(value)
	return value;

}

var weizhi= {
x: 0,
y: 0,
z: 0
};
var weizhix=0,weizhiy=0,weizhiz=0
export function init(value) {
	weizhi = value
	weizhix = value.x
	weizhiy = value.y
	weizhiz = value.z
	return value;
}

