'use strict';

import * as WEMath from 'WEMath';

// 时间设定
const FADE_IN_START_HOUR = 18;  // 开始增加透明度的时间（下午6点）
const FADE_IN_END_HOUR = 19;    // 完全透明度的时间（晚上7点）

const FADE_OUT_START_HOUR = 6;  // 开始减少透明度的时间（早上6点）
const FADE_OUT_END_HOUR = 7;    // 完全透明的时间（早上7点）

const BLEND_DURATION = 0.3;     // 渐变效果的持续时间，0.3表示18分钟渐变

// 更新透明度
export function update(value) {
    const timeOfDay = engine.timeOfDay * 24;  // 当前时间，单位为小时

    if (timeOfDay >= FADE_IN_END_HOUR && timeOfDay < FADE_OUT_START_HOUR) {
        // 在19:00到6:00之间保持透明度为1
        return 1.0;
    } else if (timeOfDay >= FADE_OUT_END_HOUR && timeOfDay < FADE_IN_START_HOUR) {
        // 在7:00到18:00之间保持透明度为0
        return 0.0;
    } else if (timeOfDay >= FADE_IN_START_HOUR && timeOfDay <= FADE_IN_END_HOUR) {
        // 在18:00到19:00之间，从0变成1
        return WEMath.smoothStep(
            (FADE_IN_START_HOUR - BLEND_DURATION) / 24,
            FADE_IN_END_HOUR / 24,
            engine.timeOfDay
        );
    } else if (timeOfDay >= FADE_OUT_START_HOUR && timeOfDay <= FADE_OUT_END_HOUR) {
        // 在6:00到7:00之间，从1变成0
        return 1.0 - WEMath.smoothStep(
            (FADE_OUT_START_HOUR - BLEND_DURATION) / 24,
            FADE_OUT_END_HOUR / 24,
            engine.timeOfDay
        );
    }

    // 默认返回透明度为0
    return 1.0;
}

visible.script:
'use strict';

// 创建可通过属性面板调整的时间段属性
export var scriptProperties = createScriptProperties()
    .addCheckbox({
        name: 'isEnabled',           // 新增的属性，用来控制图层是否根据时间显示
        label: '启用时间控制',
        value: true                  // 默认值为 true，表示启用时间控制
    })
    .addCheckbox({
        name: 'reverseMode',         // 新增反向开关
        label: '反向模式（关闭时图层始终开启）',
        value: false                 // 默认值为 false，关闭状态
    })
    .addSlider({
        name: 'visibleStart',
        label: '开始显示图层时间',
        value: 18.0,  // 默认值，表示下午6点
        min: 0.0,     // 时间从0点开始
        max: 23.999,  // 到23.999结束
        step: 0.01    // 调整精度
    })
    .addSlider({
        name: 'visibleEnd',
        label: '结束显示图层时间',
        value: 7.0,   // 默认值，表示早上7点
        min: 0.0,
        max: 23.999,
        step: 0.01
    })
    .finish();

// 该函数检查当前时间是否在给定的可见时间段内
function isLayerVisible(currentTime, startTime, endTime) {
    if (startTime < endTime) {
        // 如果时间段不跨越午夜，检查当前时间是否在开始和结束之间
        return currentTime >= startTime && currentTime < endTime;
    } else {
        // 如果时间段跨越午夜，检查当前时间是否在时间段的两侧
        return currentTime >= startTime || currentTime < endTime;
    }
}

// 更新图层的可见性
export function update(value) {
    // 获取当前时间（以小时为单位，0表示午夜，23.999接近午夜结束）
    let currentTime = engine.timeOfDay * 24.0;

    // 从属性面板中获取用户设定的时间段
    let visibleStart = scriptProperties.visibleStart;
    let visibleEnd = scriptProperties.visibleEnd;

    // 获取用户开关状态
    let isEnabled = scriptProperties.isEnabled;

    // 获取反向模式开关状态
    let reverseMode = scriptProperties.reverseMode;

    // 如果启用时间控制开关被关闭
    if (!isEnabled) {
        // 如果反向模式开启，则图层始终可见
        if (reverseMode) {
            return true;  // 始终可见
        } else {
            return false; // 始终不可见
        }
    }

    // 否则，检查当前时间是否在设定的时间范围内
    let visible = isLayerVisible(currentTime, visibleStart, visibleEnd);

    // 返回是否显示该图层
    return visible;
}

